<script setup>
import { Activity, Archive, ArrowLeft, ArrowRight, BarChart3, Check, ClipboardList, Eye, FileText, FolderTree, Hash, History, Image as ImageIcon, LayoutDashboard, LogOut, Menu, Plus, RefreshCw, Save, Search, Settings, ShieldCheck, Trash2, Upload, Users, X } from 'lucide-vue-next';
import { computed, nextTick, onMounted, ref, watch } from 'vue'; import { useRoute, useRouter } from 'vue-router';
import { categories, posts } from '../data'; import { adminRequest, apiRequest, createAdminToken } from '../api';

const route=useRoute();const router=useRouter();const authed=ref(localStorage.getItem('signal-admin-auth')==='true');const login=ref({email:'admin',password:'signal2026'});const loginError=ref('');const menuOpen=ref(false);const apiStatus=ref('正在连接数据库');
const adminPosts=ref([]);const query=ref('');const filter=ref('ALL');const users=ref([]);
const selectedPosts=ref([]);
const commentReplies=ref({});
const passwordForm=ref({currentPassword:'',newPassword:'',confirmPassword:''});
const comments=ref([]);const media=ref([]);const settings=ref({siteName:'脉冲笔记',tagline:'把复杂技术讲清楚',shareTemplate:'横版卡片',comments:true});const saved=ref('');const backup=ref('暂无备份');const logs=ref([]);const backupJobs=ref([]);const dashboardData=ref({views:0,errors:0,popular:[],trend:[]});const timeRange=ref(7);
const nav=[['/admin','仪表盘',LayoutDashboard],['/admin/posts','文章',FileText],['/admin/taxonomy','分类与标签',FolderTree],['/admin/media','媒体库',ImageIcon],['/admin/comments','评论',ClipboardList],['/admin/users','用户',Users],['/admin/settings','设置',Settings],['/admin/logs','日志与备份',Activity]];
const section=computed(()=>route.path.split('/')[2]||'dashboard');const editorMode=computed(()=>route.path.includes('/posts/new')||route.path.includes('/edit'));const filteredPosts=computed(()=>adminPosts.value.filter(p=>(!query.value||p.title.includes(query.value))&&(filter.value==='ALL'||p.status===filter.value)));
const editId=computed(()=>route.params.pathMatch?.[1]);const editor=ref({});const editorReady=ref(false);const previewing=ref(false);const revisions=ref([]);const categoriesAdmin=ref([]);const tagsAdmin=ref([]);const taxonomyDraft=ref({name:'',slug:'',description:''});const tagDraft=ref('');
const publishChecklist=computed(()=>[{label:'标题',ok:Boolean(editor.value.title?.trim())},{label:'Slug',ok:Boolean(editor.value.slug?.trim())},{label:'正文',ok:editor.value.content?.trim().length>40},{label:'分类',ok:Boolean(editor.value.category)},{label:'封面替代文本',ok:Boolean(editor.value.coverAlt?.trim())},{label:'SEO 标题与描述',ok:Boolean(editor.value.seoTitle?.trim()&&editor.value.seoDescription?.trim())}]);
function syncEditor(){if(!editorMode.value)return;editorReady.value=false;const id=editId.value;const existing=id?adminPosts.value.find(p=>String(p.id)===String(id)):null;editor.value=existing?{...existing}:{id:`post-${Date.now()}`,title:'',slug:'',excerpt:'',content:'',category:'人工智能',tags:[],status:'DRAFT',cover:'/assets/hero-circuit.jpg',coverAlt:'',readMinutes:5,seoTitle:'',seoDescription:'',canonicalUrl:'',pinned:false,scheduledAt:null};nextTick(()=>{editorReady.value=true;});}
watch(()=>route.path,()=>{menuOpen.value=false;syncEditor();if(editorMode.value)loadRevisions();},{immediate:true});
onMounted(async()=>{if(authed.value) await loadAdminData();});
async function loadAdminData(){try{const [dashboard,postData,commentData,userData,settingData,mediaData,taxonomy,tagsData,logData,backupData]=await Promise.all([adminRequest('/admin/dashboard'),adminRequest('/admin/posts'),adminRequest('/admin/comments'),adminRequest('/admin/users'),adminRequest('/admin/settings'),apiRequest('/media'),adminRequest('/admin/categories'),adminRequest('/admin/tags'),adminRequest('/admin/logs'),adminRequest('/admin/backups')]);adminPosts.value=postData||[];comments.value=commentData||[];users.value=userData||[];settings.value={...settings.value,...settingData};media.value=mediaData||[];categoriesAdmin.value=taxonomy||[];tagsAdmin.value=tagsData||[];logs.value=logData||[];backupJobs.value=backupData||[];dashboardData.value=dashboard;backup.value=backupJobs.value[0]?.createdAt?.slice(0,16).replace('T',' ')||'暂无备份';apiStatus.value=`MySQL 已连接 · ${dashboard.posts} 篇文章`;syncEditor();}catch(error){apiStatus.value='后端未连接';loginError.value=error.message||'后台数据加载失败，请检查后端服务';}}
async function doLogin(){loginError.value='';const token=createAdminToken(login.value.email,login.value.password);try{localStorage.setItem('signal-admin-token',token);await apiRequest('/admin/dashboard',{headers:{Authorization:`Basic ${token}`}});authed.value=true;localStorage.setItem('signal-admin-auth','true');await loadAdminData();}catch(error){localStorage.removeItem('signal-admin-token');localStorage.removeItem('signal-admin-auth');authed.value=false;loginError.value=error.message||'账号或密码不正确';}}
function logout(){authed.value=false;localStorage.removeItem('signal-admin-auth');localStorage.removeItem('signal-admin-token');router.push('/admin');}
async function savePost(status=editor.value.status,silent=false){const value={...editor.value,status,publishedAt:status==='PUBLISHED'?(editor.value.publishedAt||new Date().toISOString().slice(0,10)):editor.value.publishedAt||null,tags:Array.isArray(editor.value.tags)?editor.value.tags:String(editor.value.tags||'').split(',').map(t=>t.trim()).filter(Boolean)};try{const payload={slug:value.slug||value.title.toLowerCase().replace(/\s+/g,'-'),title:value.title,excerpt:value.excerpt||'',content:value.content||'',cover:value.cover,coverAlt:value.coverAlt,category:value.category,tags:value.tags,status:value.status,authorName:'林默',publishedAt:value.publishedAt,readMinutes:Number(value.readMinutes)||5,scheduledAt:value.scheduledAt||null,seoTitle:value.seoTitle||value.title,seoDescription:value.seoDescription||value.excerpt,canonicalUrl:value.canonicalUrl||null,pinned:Boolean(value.pinned)};const result=value.id&&Number.isFinite(Number(value.id))?await adminRequest(`/admin/posts/${value.id}`,{method:'PUT',body:JSON.stringify(payload)}):await adminRequest('/admin/posts',{method:'POST',body:JSON.stringify(payload)});Object.assign(value,result);Object.assign(editor.value,result);apiStatus.value='MySQL 已连接';const i=adminPosts.value.findIndex(p=>String(p.id)===String(value.id));if(i>=0)adminPosts.value[i]=value;else adminPosts.value.unshift(value);saved.value=silent?'自动保存完成':status==='PUBLISHED'?'文章已发布':'草稿已保存';if(!silent)setTimeout(()=>{saved.value='';if(status==='PUBLISHED')router.push('/admin/posts');},500);}catch(error){apiStatus.value='后端未连接';saved.value=error.message||'保存失败，请检查后端服务';}}
let autosaveTimer;watch(editor,()=>{if(!editorReady.value||!editorMode.value)return;clearTimeout(autosaveTimer);saved.value='有未保存修改';autosaveTimer=setTimeout(()=>savePost('DRAFT',true),1000);},{deep:true});
async function loadRevisions(){if(!editId.value||!Number.isFinite(Number(editId.value)))return;try{revisions.value=await adminRequest(`/admin/posts/${editId.value}/revisions`);}catch{revisions.value=[];}}
async function restoreRevision(id){if(!confirm('恢复此版本会创建新的草稿版本，继续吗？'))return;try{const result=await adminRequest(`/admin/posts/${editId.value}/revisions/${id}/restore`,{method:'POST'});editor.value={...editor.value,...result};saved.value='已恢复为新草稿';await loadRevisions();}catch{saved.value='恢复失败，请重试';}}
async function deletePost(post){const permanent=post.status==='TRASHED';const prompt=permanent?'永久删除后无法恢复，确定继续吗？':'移入回收站后可恢复，确定继续吗？';if(!confirm(prompt))return;try{await adminRequest(`/admin/posts/${post.id}${permanent?'?permanent=true':''}`,{method:'DELETE'});if(permanent)adminPosts.value=adminPosts.value.filter(item=>item.id!==post.id);else post.status='TRASHED';saved.value=permanent?'文章已永久删除':'文章已移入回收站';}catch(error){saved.value=error.message||'文章删除失败，请重试';}}
async function restorePost(post){try{const result=await adminRequest(`/admin/posts/${post.id}/restore`,{method:'POST'});Object.assign(post,result);saved.value='文章已恢复为草稿';}catch(error){saved.value=error.message||'文章恢复失败，请重试';}}
async function createCategory(){if(!taxonomyDraft.value.name.trim()||!taxonomyDraft.value.slug.trim())return;try{const result=await adminRequest('/admin/categories',{method:'POST',body:JSON.stringify(taxonomyDraft.value)});categoriesAdmin.value.push(result);taxonomyDraft.value={name:'',slug:'',description:''};}catch{saved.value='分类名称或别名已存在';}}
async function createTag(){if(!tagDraft.value.trim())return;try{const result=await adminRequest('/admin/tags',{method:'POST',body:JSON.stringify({name:tagDraft.value,slug:tagDraft.value.toLowerCase().replace(/\s+/g,'-')})});tagsAdmin.value.push(result);tagDraft.value='';}catch{saved.value='标签已存在';}}
async function saveCategory(item){try{await adminRequest(`/admin/categories/${item.id}`,{method:'PUT',body:JSON.stringify(item)});saved.value='分类已更新';}catch{saved.value='分类更新失败，请检查名称和别名';}}
async function removeCategory(item){try{await adminRequest(`/admin/categories/${item.id}`,{method:'DELETE'});categoriesAdmin.value=categoriesAdmin.value.filter(value=>value.id!==item.id);saved.value='分类已删除';}catch{saved.value='分类仍被文章引用，无法删除';}}
async function saveTag(item){try{await adminRequest(`/admin/tags/${item.id}`,{method:'PUT',body:JSON.stringify(item)});saved.value='标签已更新，关联文章已同步';}catch{saved.value='标签更新失败，请检查名称和别名';}}
async function removeTag(item){try{await adminRequest(`/admin/tags/${item.id}`,{method:'DELETE'});tagsAdmin.value=tagsAdmin.value.filter(value=>value.id!==item.id);saved.value='标签已删除';}catch{saved.value='标签仍被文章引用，无法删除';}}
async function toggleUser(user){const previous=user.status;user.status=user.status==='ACTIVE'||user.status==='正常'?'DISABLED':'ACTIVE';try{await adminRequest(`/admin/users/${user.id}`,{method:'PATCH',body:JSON.stringify({status:user.status})});saved.value='用户状态已更新，会话已失效';}catch{user.status=previous;saved.value='用户状态更新失败';}}
async function bulkStatus(status){if(!selectedPosts.value.length)return;try{await adminRequest('/admin/posts/batch',{method:'PATCH',body:JSON.stringify({ids:selectedPosts.value.map(Number),status})});adminPosts.value.forEach(post=>{if(selectedPosts.value.map(String).includes(String(post.id))){post.status=status;post.deletedAt=status==='TRASHED'?new Date().toISOString():null;}});saved.value=`已更新 ${selectedPosts.value.length} 篇文章`;selectedPosts.value=[];}catch(error){saved.value=error.message||'批量操作失败，请重试';}}
async function runBackup(){saved.value='正在导出并校验备份';try{const result=await adminRequest('/admin/backups',{method:'POST'});backupJobs.value.unshift(result);backup.value=result.createdAt.slice(0,16).replace('T',' ');saved.value=`备份完成 · ${result.size} bytes · SHA-256 已校验`;}catch{saved.value='备份失败，请查看服务日志';}}
async function saveSettings(){try{await adminRequest('/admin/settings',{method:'PUT',body:JSON.stringify(settings.value)});apiStatus.value='MySQL 已连接';saved.value='设置已保存';setTimeout(()=>saved.value='',1800);}catch(error){apiStatus.value='后端未连接';saved.value=error.message||'设置保存失败，请检查后端服务';}}
async function changePassword(){const value=passwordForm.value;if(value.newPassword.length<10){saved.value='新密码至少需要 10 个字符';return;}if(value.newPassword!==value.confirmPassword){saved.value='两次输入的新密码不一致';return;}try{await adminRequest('/admin/account/password',{method:'PUT',body:JSON.stringify({currentPassword:value.currentPassword,newPassword:value.newPassword})});localStorage.removeItem('signal-admin-token');localStorage.removeItem('signal-admin-auth');authed.value=false;passwordForm.value={currentPassword:'',newPassword:'',confirmPassword:''};login.value.password='';loginError.value='密码已更新，请使用新密码登录';}catch{saved.value='当前密码不正确或新密码不符合要求';}}
async function moderate(item,status){item.status=status;try{await adminRequest(`/admin/comments/${item.id}`,{method:'PATCH',body:JSON.stringify({status})});}catch{}}
async function replyComment(item){const content=(commentReplies.value[item.id]||'').trim();if(content.length<2){saved.value='回复至少需要 2 个字';return;}try{const result=await adminRequest(`/admin/comments/${item.id}/reply`,{method:'POST',body:JSON.stringify({content})});comments.value.push(result);commentReplies.value[item.id]='';saved.value='回复已发布';}catch{saved.value='回复发布失败，请重试';}}
async function deleteComment(item){comments.value=comments.value.filter(c=>c.id!==item.id);try{await adminRequest(`/admin/comments/${item.id}`,{method:'DELETE'});}catch{}}
async function uploadMedia(event){for(const file of event.target.files||[]){try{const body=new FormData();body.append('file',file);const result=await adminRequest('/admin/media',{method:'POST',headers:{},body});media.value.unshift(result);saved.value='媒体已上传';}catch(error){saved.value=error.message||'媒体上传失败，请重试';}}event.target.value='';}
async function saveMedia(item){try{const result=await adminRequest(`/admin/media/${item.id}`,{method:'PATCH',body:JSON.stringify({filename:item.filename,altText:item.altText||''})});Object.assign(item,result);saved.value='媒体信息已保存';}catch(error){saved.value=error.message||'媒体信息保存失败';}}
async function deleteMedia(item){if(!confirm(`确定删除“${item.filename}”？`))return;try{await adminRequest(`/admin/media/${item.id}`,{method:'DELETE'});media.value=media.value.filter(value=>value.id!==item.id);saved.value='媒体已删除';}catch(error){saved.value=error.message||'媒体删除失败，请先检查文章封面引用';}}
</script>

<template>
  <main v-if="!authed" class="admin-login"><div class="admin-login-mark"><span /><span /><span /></div><span class="admin-kicker">SIGNAL NOTES / ADMIN</span><h1>管理你的<br />技术记录。</h1><p>发布文章、整理媒体和处理读者反馈。</p><form @submit.prevent="doLogin"><label>管理员账号<input v-model="login.email" autocomplete="username" /></label><label>密码<input v-model="login.password" type="password" autocomplete="current-password" /></label><button class="button button-primary">进入后台 <ArrowRight :size="17" /></button><small v-if="loginError">{{loginError}}</small></form><span class="admin-demo-hint">演示账号：admin / signal2026</span></main>
  <div v-else class="admin-shell"><aside :class="{'is-open':menuOpen}"><div class="admin-aside-brand"><span class="brand-mark"><i /><i /><i /></span><div><b>脉冲笔记</b><small>ADMIN / CONSOLE</small></div></div><nav><RouterLink v-for="item in nav" :key="item[0]" :to="item[0]"><component :is="item[2]" :size="17" />{{item[1]}}<em v-if="item[1]==='评论'">{{comments.filter(c=>c.status==='PENDING').length}}</em></RouterLink></nav><div class="admin-aside-bottom"><RouterLink to="/blog"><ArrowRight :size="15" />查看站点</RouterLink><button @click="logout"><LogOut :size="15" />退出登录</button></div></aside><div class="admin-body"><header class="admin-topbar"><button class="admin-menu-toggle" @click="menuOpen=!menuOpen"><X v-if="menuOpen" :size="19" /><Menu v-else :size="19" /></button><div class="admin-breadcrumb">ADMIN <span>/</span> SIGNAL NOTES</div><div class="admin-top-actions"><span class="admin-online"><i />{{apiStatus}}</span><span class="admin-user">林默 · 管理员</span></div></header>
    <main v-if="editorMode" class="admin-content editor-page"><div class="editor-top"><RouterLink to="/admin/posts"><ArrowLeft :size="16" />文章列表</RouterLink><div><span>{{saved||'等待输入'}}</span><button class="button" @click="previewing=!previewing"><Eye :size="15" />{{previewing?'返回编辑':'预览'}}</button><button class="button" @click="savePost('DRAFT')"><Save :size="15" />保存草稿</button><button class="button button-primary" :disabled="publishChecklist.some(item=>!item.ok)" @click="savePost('PUBLISHED')">发布 <ArrowRight :size="15" /></button></div></div><div v-if="previewing" class="editor-live-preview"><span>仅管理员可见 · 当前草稿预览</span><h1>{{editor.title||'未命名文章'}}</h1><p>{{editor.excerpt}}</p><pre>{{editor.content}}</pre></div><div v-else class="editor-grid"><section class="editor-main"><textarea v-model="editor.title" class="editor-title" rows="2" maxlength="240" placeholder="文章标题" /><textarea v-model="editor.excerpt" class="editor-excerpt" rows="3" placeholder="写一段摘要" /><textarea v-model="editor.content" class="editor-content" placeholder="使用 Markdown 写作..." /><footer class="editor-statusbar"><span>{{(editor.content||'').length}} 字</span><span>约 {{Math.max(1,Math.ceil((editor.content||'').length/500))}} 分钟</span><button type="button" @click="loadRevisions"><History :size="14" />版本历史</button></footer></section><aside class="editor-sidebar"><div class="editor-card"><h3>发布设置</h3><label>状态<select v-model="editor.status"><option value="DRAFT">草稿</option><option value="PENDING">待审核</option><option value="SCHEDULED">定时发布</option><option value="PUBLISHED">已发布</option><option value="OFFLINE">已下线</option><option value="TRASHED">回收站</option></select></label><label v-if="editor.status==='SCHEDULED'">计划时间<input v-model="editor.scheduledAt" type="datetime-local" /></label><label>分类<select v-model="editor.category"><option v-for="cat in (categoriesAdmin.length?categoriesAdmin:categories)" :key="cat.name">{{cat.name}}</option></select></label><label>标签<input v-model="editor.tags" placeholder="AI, 工程" /></label><label>预计阅读分钟<input v-model.number="editor.readMinutes" type="number" min="1" /></label><label class="admin-check"><input v-model="editor.pinned" type="checkbox" />置顶文章</label></div><div class="editor-card"><h3>SEO 与媒体</h3><label>Slug<input v-model="editor.slug" /></label><label>SEO 标题<input v-model="editor.seoTitle" maxlength="240" /></label><label>SEO 描述<textarea v-model="editor.seoDescription" rows="3" maxlength="320" /></label><label>Canonical URL<input v-model="editor.canonicalUrl" type="url" /></label><label>封面 URL<input v-model="editor.cover" /></label><label>图片替代文本<input v-model="editor.coverAlt" /></label></div><div class="editor-card publish-checklist"><h3>发布检查</h3><div v-for="item in publishChecklist" :key="item.label" :class="{ok:item.ok}"><Check :size="14" />{{item.label}}</div></div><div v-if="revisions.length" class="editor-card revision-list"><h3>版本历史</h3><button v-for="item in revisions" :key="item.id" type="button" @click="restoreRevision(item.id)"><span>#{{item.versionNo}} · {{item.editor}}</span><small>{{item.changeSummary}}</small></button></div></aside></div></main>
    <main v-else class="admin-content">
      <section v-if="section==='posts'" class="admin-panel admin-quick-actions"><div class="panel-heading"><div><span>QUICK ACTIONS</span><h2>文章操作</h2></div><small>删除会先进入回收站，回收站文章可恢复或永久删除。</small></div><div class="quick-action-list"><div v-for="post in filteredPosts" :key="`action-${post.id}`"><strong>{{post.title}}</strong><span>{{post.status}}</span><span class="quick-action-buttons"><RouterLink class="icon-button" :to="`/admin/posts/${post.id}/edit`" title="编辑文章" :aria-label="`编辑 ${post.title}`"><FileText :size="15" /></RouterLink><button v-if="post.status!=='TRASHED'" class="icon-button danger" type="button" title="移入回收站" :aria-label="`删除 ${post.title}`" @click="deletePost(post)"><Trash2 :size="15" /></button><button v-else class="icon-button" type="button" title="恢复文章" :aria-label="`恢复 ${post.title}`" @click="restorePost(post)"><RefreshCw :size="15" /></button><button v-if="post.status==='TRASHED'" class="icon-button danger" type="button" title="永久删除" :aria-label="`永久删除 ${post.title}`" @click="deletePost(post)"><Trash2 :size="15" /></button></span></div><p v-if="!filteredPosts.length" class="admin-empty">暂无文章，先创建一篇文章。</p></div></section>
      <section v-if="section==='media'" class="admin-panel admin-quick-actions"><div class="panel-heading"><div><span>FILE ACTIONS</span><h2>媒体操作</h2></div><small>被文章封面引用的媒体需要先替换引用。</small></div><div class="quick-action-list"><div v-for="item in media" :key="`media-action-${item.id}`"><strong>{{item.filename}}</strong><span>{{item.mimeType}} · {{item.size}} bytes</span><span class="quick-action-buttons"><button class="icon-button danger" type="button" title="删除媒体" :aria-label="`删除 ${item.filename}`" @click="deleteMedia(item)"><Trash2 :size="15" /></button></span></div><p v-if="!media.length" class="admin-empty">还没有上传媒体。</p></div></section>
      <template v-if="section==='dashboard'"><header class="admin-page-header"><div><span>OVERVIEW / 001</span><h1>早上好，林默。</h1><p>这里是你的内容工作台，统计口径为数据库当前快照。</p></div><RouterLink class="button button-primary" to="/admin/posts/new"><Plus :size="17" />新建文章</RouterLink></header><section class="admin-stat-grid"><div class="admin-stat"><FileText :size="18" /><span>已发布文章</span><strong>{{dashboardData.published||adminPosts.filter(p=>p.status==='PUBLISHED').length}}</strong><small>当前状态</small></div><div class="admin-stat"><ClipboardList :size="18" /><span>待处理评论</span><strong>{{dashboardData.pendingComments||comments.filter(c=>c.status==='PENDING').length}}</strong><small>需要审核</small></div><div class="admin-stat"><Archive :size="18" /><span>草稿</span><strong>{{dashboardData.drafts||adminPosts.filter(p=>p.status==='DRAFT').length}}</strong><small>继续编辑</small></div><div class="admin-stat"><BarChart3 :size="18" /><span>累计访问量</span><strong>{{dashboardData.views||0}}</strong><small>去重口径见日志</small></div></section><section class="admin-dashboard-grid"><section class="admin-panel chart-panel"><div class="panel-heading"><div><span>RECENT NOTES</span><h2>最近文章</h2></div><RouterLink to="/admin/posts">查看全部</RouterLink></div><div class="admin-table compact"><RouterLink v-for="post in adminPosts.slice(0,6)" :key="post.id" class="table-row" :to="`/admin/posts/${post.id}/edit`"><strong>{{post.title}}</strong><span>{{post.category}}</span><span class="status">{{post.status}}</span><time>{{post.updatedAt}}</time></RouterLink></div></section><section class="admin-panel chart-panel"><div class="panel-heading"><div><span>POPULAR / {{timeRange}} DAYS</span><h2>热门文章</h2></div><select v-model="timeRange"><option :value="7">7 天</option><option :value="30">30 天</option><option :value="90">90 天</option></select></div><div class="popular-list"><div v-for="item in dashboardData.popular" :key="item.id"><strong>{{item.title}}</strong><span>{{item.views}} 阅读</span></div><p v-if="!dashboardData.popular?.length" class="admin-empty">暂无统计数据</p></div></section></section></template>
      <template v-else-if="section==='posts'"><header class="admin-page-header"><div><span>CONTENT / POSTS</span><h1>文章</h1><p>{{adminPosts.length}} 篇内容，按状态和更新时间管理。</p></div><RouterLink class="button button-primary" to="/admin/posts/new"><Plus :size="17" />新建文章</RouterLink></header><div v-if="saved" class="admin-success">{{saved}}</div><div class="admin-toolbar"><div class="admin-search"><Search :size="16" /><input v-model="query" placeholder="搜索标题" /></div><div class="segmented"><button v-for="item in ['ALL','PUBLISHED','DRAFT','PENDING','SCHEDULED','OFFLINE','TRASHED']" :key="item" :class="{active:filter===item}" @click="filter=item">{{item}}</button></div></div><div v-if="selectedPosts.length" class="bulk-bar"><strong>已选择 {{selectedPosts.length}} 篇</strong><button @click="bulkStatus('PUBLISHED')">发布</button><button @click="bulkStatus('OFFLINE')">下线</button><button @click="bulkStatus('TRASHED')">移入回收站</button><button @click="bulkStatus('DRAFT')">恢复为草稿</button></div><section class="admin-panel"><div class="admin-table post-admin-table"><div class="table-head"><span>选择</span><span>文章</span><span>分类</span><span>状态</span><span>更新时间</span><span>操作</span></div><div v-for="post in filteredPosts" :key="post.id" class="table-row"><input v-model="selectedPosts" type="checkbox" :value="String(post.id)" :aria-label="`选择 ${post.title}`" /><RouterLink :to="`/admin/posts/${post.id}/edit`"><strong>{{post.title}}</strong><small>{{post.excerpt}}</small></RouterLink><span>{{post.category}}</span><span class="status">{{post.status}}</span><time>{{post.updatedAt}}</time><RouterLink :to="`/admin/posts/${post.id}/edit`"><FileText :size="15" /></RouterLink></div></div></section></template>
      <template v-else-if="section==='taxonomy'"><header class="admin-page-header"><div><span>CONTENT / TAXONOMY</span><h1>分类与标签</h1><p>新增、编辑和删除都执行唯一性与文章引用检查。</p></div></header><div v-if="saved" class="admin-success">{{saved}}</div><div class="taxonomy-layout"><section class="admin-panel taxonomy-panel"><div class="panel-heading"><div><span>CATEGORIES</span><h2>分类</h2></div></div><form class="taxonomy-form" @submit.prevent="createCategory"><input v-model="taxonomyDraft.name" placeholder="分类名称" /><input v-model="taxonomyDraft.slug" placeholder="unique-slug" /><input v-model="taxonomyDraft.description" placeholder="分类说明" /><button class="button button-primary"><Plus :size="15" />新增分类</button></form><div class="taxonomy-list taxonomy-edit-list"><div v-for="item in (categoriesAdmin.length?categoriesAdmin:categories)" :key="item.id||item.name"><FolderTree :size="16" /><div><input v-model="item.name" aria-label="分类名称" /><input v-model="item.slug" aria-label="分类别名" /><input v-model="item.description" aria-label="分类说明" /></div><button class="row-text-button" @click="saveCategory(item)">保存</button><button class="icon-button" title="删除分类" @click="removeCategory(item)"><Trash2 :size="14" /></button></div></div></section><section class="admin-panel taxonomy-panel"><div class="panel-heading"><div><span>TAGS</span><h2>标签</h2></div></div><form class="taxonomy-form tag-create" @submit.prevent="createTag"><input v-model="tagDraft" placeholder="新标签名称" /><button class="button button-primary"><Plus :size="15" />新增标签</button></form><div class="taxonomy-list tag-list taxonomy-edit-list"><div v-for="item in tagsAdmin" :key="item.id"><Hash :size="15" /><div><input v-model="item.name" aria-label="标签名称" /><input v-model="item.slug" aria-label="标签别名" /></div><button class="row-text-button" @click="saveTag(item)">保存</button><button class="icon-button" title="删除标签" @click="removeTag(item)"><Trash2 :size="14" /></button></div><p v-if="!tagsAdmin.length" class="admin-empty">保存文章时会同步标签；也可以在这里预先创建。</p></div></section></div></template>
      <template v-else-if="section==='media'"><header class="admin-page-header"><div><span>LIBRARY / MEDIA</span><h1>媒体库</h1><p>上传、预览并维护文件名和图片替代文本。</p></div><label class="button button-primary"><Upload :size="16" />上传文件<input type="file" hidden multiple accept="image/jpeg,image/png,image/webp" @change="uploadMedia" /></label></header><div v-if="saved" class="admin-success">{{saved}}</div><section class="media-grid"><article v-for="item in (media.length?media:[{id:'hero',filename:'hero-circuit.jpg',url:'/assets/hero-circuit.jpg',mimeType:'image/jpeg'},{id:'work',filename:'workstation.jpg',url:'/assets/workstation.jpg',mimeType:'image/jpeg'}])" :key="item.id"><div class="media-thumb"><img :src="item.url" :alt="item.altText||item.filename" /></div><div class="media-fields"><label>文件名<input v-model="item.filename" /></label><label>替代文本<input v-model="item.altText" /></label><span>{{item.mimeType}} · {{item.size||'本地资源'}} bytes</span><button v-if="Number.isFinite(Number(item.id))" class="row-text-button" @click="saveMedia(item)">保存信息</button></div></article></section></template>
      <template v-else-if="section==='comments'"><header class="admin-page-header"><div><span>COMMUNITY / MODERATION</span><h1>评论审核</h1><p>{{comments.filter(c=>c.status==='PENDING').length}} 条评论等待处理，举报内容会显示复核原因。</p></div></header><div v-if="saved" class="admin-success">{{saved}}</div><section class="admin-panel moderation-list"><article v-for="item in comments" :key="item.id"><div class="moderation-meta"><strong>{{item.authorName}}</strong><span class="risk-tag">{{item.reportCount ? `举报 ${item.reportCount}` : item.status}}</span></div><p>{{item.content}}</p><small>文章：{{item.postSlug}}<template v-if="item.reportReason"> · 原因：{{item.reportReason}}</template></small><div class="moderation-actions"><button class="button button-primary" @click="moderate(item,'APPROVED')"><Check :size="15" />通过</button><button class="button" @click="moderate(item,'SPAM')">标记垃圾</button><button class="button" @click="deleteComment(item)"><Trash2 :size="15" />删除</button></div><form class="moderation-reply" @submit.prevent="replyComment(item)"><input v-model="commentReplies[item.id]" maxlength="2000" placeholder="以站点管理员身份回复" /><button class="row-text-button">发布回复</button></form></article></section></template>
      <template v-else-if="section==='users'"><header class="admin-page-header"><div><span>ACCESS / USERS</span><h1>用户与角色</h1><p>最小权限原则，关键变更写入操作日志。</p></div><button class="button button-primary"><Plus :size="16" />邀请用户</button></header><div v-if="saved" class="admin-success">{{saved}}</div><section class="admin-panel"><div class="admin-table user-table"><div class="table-head"><span>用户</span><span>角色</span><span>状态</span><span>最近登录</span><span>操作</span></div><div v-for="user in users" :key="user.id" class="table-row"><div><strong>{{user.name}}</strong><small>{{user.email}}</small></div><span>{{user.role}}</span><span>{{user.status}}</span><time>今天</time><button class="row-text-button" @click="toggleUser(user)">{{user.status==='ACTIVE'||user.status==='正常'?'禁用':'启用'}}</button></div></div></section></template>
      <template v-else-if="section==='settings'"><header class="admin-page-header"><div><span>SYSTEM / SETTINGS</span><h1>站点设置</h1><p>基础信息、分享模板和账户安全。</p></div><button class="button button-primary" @click="saveSettings"><Save :size="15" />保存设置</button></header><div v-if="saved" class="admin-success"><Check :size="15" />{{saved}}</div><div class="settings-grid"><section class="admin-panel settings-panel"><div class="panel-heading"><div><span>GENERAL</span><h2>基础信息</h2></div></div><label>站点名称<input v-model="settings.siteName" /></label><label>站点定位语<textarea v-model="settings.tagline" /></label></section><section class="admin-panel settings-panel"><div class="panel-heading"><div><span>SHARE / POSTER</span><h2>分享海报</h2></div></div><label>默认模板<select v-model="settings.shareTemplate"><option>横版卡片</option><option>竖版海报</option></select></label><div class="share-setting-preview"><span>SIGNAL NOTES</span><strong>{{settings.siteName}}</strong><small>{{settings.tagline}}</small><i>QR</i></div></section><section class="admin-panel settings-panel"><div class="panel-heading"><div><span>ACCOUNT / SECURITY</span><h2>修改密码</h2></div></div><form class="account-form" @submit.prevent="changePassword"><label>当前密码<input v-model="passwordForm.currentPassword" type="password" autocomplete="current-password" /></label><label>新密码<input v-model="passwordForm.newPassword" type="password" minlength="10" autocomplete="new-password" /></label><label>确认新密码<input v-model="passwordForm.confirmPassword" type="password" minlength="10" autocomplete="new-password" /></label><button class="button">更新并重新登录</button></form></section></div></template>
      <template v-else><header class="admin-page-header"><div><span>SYSTEM / AUDIT</span><h1>日志、任务与备份</h1><p>重要变更写入审计日志，备份文件包含 SHA-256 校验。</p></div><button class="button button-primary" @click="runBackup"><Archive :size="15" />立即备份</button></header><div v-if="saved" class="admin-success">{{saved}}</div><div class="log-status-grid"><div><ShieldCheck :size="20" /><span>安全响应头</span><strong>CSP 已启用</strong><small>写接口含频率限制</small></div><div><Archive :size="20" /><span>最近备份</span><strong>{{backup}}</strong><small>{{backupJobs[0]?.size||0}} bytes</small></div><div><Activity :size="20" /><span>错误任务</span><strong>{{dashboardData.errors||0}}</strong><small>数据库审计口径</small></div></div><div class="operations-grid"><section class="admin-panel"><div class="panel-heading"><div><span>AUDIT LOG</span><h2>最近操作</h2></div></div><div class="operation-list"><div v-for="item in logs" :key="item.id"><span>{{item.action}}</span><strong>{{item.target}}</strong><small>{{item.actor}} · {{item.createdAt?.slice(0,19).replace('T',' ')}} · {{item.result}}</small></div><p v-if="!logs.length" class="admin-empty">暂无操作日志</p></div></section><section class="admin-panel"><div class="panel-heading"><div><span>BACKUP TASKS</span><h2>备份记录</h2></div></div><div class="operation-list"><div v-for="item in backupJobs" :key="item.id"><span>{{item.status}}</span><strong>{{item.filename}}</strong><small>{{item.size}} bytes · {{item.checksum?.slice(0,16)}}…</small></div><p v-if="!backupJobs.length" class="admin-empty">还没有备份，点击右上角开始。</p></div></section></div></template>
    </main>
  </div></div>
</template>
